# Generate candidate marking 5 runs of length 3 (for contingency)
out5=[row[:] for row in grid]
for r in range(len(grid)-2):
 for c in range(len(grid[0])):
  if all(grid[x][c]==5 for x in range(r,r+3)):
   for x in range(r,r+3): out5[x][c]=1
for r,row in enumerate(grid):
 for c in range(len(row)-2):
  if all(row[x]==5 for x in range(c,c+3)):
   for x in range(c,c+3): out5[r][x]=1
print('\n'.join(' '.join(map(str,row)) for row in out5))

# create diagonal-inclusive candidate
rr=[x[:] for x in grid]; H=len(grid); W=len(grid[0])
for r in range(H):
 for c in range(W):
  for dr,dc in [(0,1),(1,0),(1,1),(1,-1)]:
   pts=[(r+i*dr,c+i*dc) for i in range(3)]
   if all(0<=x<H and 0<=y<W and grid[x][y]==0 for x,y in pts):
    for x,y in pts: rr[x][y]=1
print('\n'.join(' '.join(map(str,row)) for row in rr))

# components of zero with 4-neighborhood; color exact 3-cell vertical/horizontal components
H,W=len(grid),len(grid[0]); seen=set(); outc=[row[:] for row in grid]
for r in range(H):
 for c in range(W):
  if grid[r][c]!=0 or (r,c) in seen: continue
  stack=[(r,c)];seen.add((r,c)); comp=[]
  while stack:
   x,y=stack.pop();comp.append((x,y))
   for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
    if 0<=a<H and 0<=b<W and grid[a][b]==0 and (a,b) not in seen:seen.add((a,b));stack.append((a,b))
  if len(comp)==3:
   xs=[x for x,y in comp];ys=[y for x,y in comp]
   if (max(xs)-min(xs)==2 and len(set(ys))==1) or (max(ys)-min(ys)==2 and len(set(xs))==1):
    for x,y in comp:outc[x][y]=1
print('\n'.join(' '.join(map(str,row)) for row in outc))

# mark triples of zeros whose 8-neighbor perimeter around the 3-cell line contains no zeros
outx=[r[:] for r in grid]; H=len(grid); W=len(grid[0])
for r in range(H):
 for c in range(W):
  for dr,dc in [(0,1),(1,0)]:
   pts=[(r+i*dr,c+i*dc) for i in range(3)]
   if not all(0<=x<H and 0<=y<W and grid[x][y]==0 for x,y in pts): continue
   cells=set()
   for x,y in pts:
    for a in range(x-1,x+2):
     for b in range(y-1,y+2):
      if 0<=a<H and 0<=b<W and (a,b) not in pts: cells.add((a,b))
   if all(grid[a][b]!=0 for a,b in cells):
    for x,y in pts:outx[x][y]=1
print('\n'.join(' '.join(map(str,row)) for row in outx))
